import{_ as a,c as i,o as p,ah as e}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"《序卦传》","description":"周易折中 - 《序卦传》","frontmatter":{"title":"《序卦传》","description":"周易折中 - 《序卦传》"},"headers":[],"relativePath":"zh/classics/zhezhong/076.md","filePath":"zh/classics/zhezhong/076.md"}'),r={name:"zh/classics/zhezhong/076.md"};function h(n,l,d,t,s,o){return p(),i("div",null,[...l[0]||(l[0]=[e('<h1 id="《序卦传》" tabindex="-1">《序卦传》 <a class="header-anchor" href="#《序卦传》" aria-label="Permalink to “《序卦传》”">​</a></h1><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰 ：韩康伯云序卦之所明非易之蕴也，盖因卦之次托象以明义。今验六十四卦二二相偶，非覆即变。覆者表里视之，遂成两卦；屯蒙需讼师比之类是也。变者反复惟成一卦，则变以对之；乾坤坎离大过颐中孚小过之类是也。且圣人本定先后，若元用孔子序卦之意，则不应非覆即变。然则康伯所云因卦之次托象以明义，盖不虚矣。</p></li><li><p>张子曰 ：序卦相受，圣人作易须有次序。</p></li><li><p>朱子语类 ：问序卦或以为非圣人之书，信乎曰？此沙随程氏之说也。先儒以为非圣人之蕴，某以为非圣人之精则可谓，非易之蕴则不可。周子分精与蕴字甚分明，序卦却正是易之蕴，事事夹杂都有在里面。 问如何谓易之精曰：如易有太极是生两仪，两仪生四象，四象生八卦，这是易之精。 问如序卦中亦见消长进退之义，唤作不是精不得曰：此正是事事夹杂有在里面，正是蕴。须是自一个生出，以至于无穷，便是精。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>卦之所以序者必自有故，而孔子以义次之。就其所次，亦足以见天道之盈虚消长，人事之得失存亡，国家之兴衰理乱。如孔氏朱子之言皆是也。然须知若别为之序，则其理亦未尝不相贯。如蓍筮之法，一卦可变为六十四卦，随其所遇而其贞与悔皆可以相生。然后有以周义理而极事变，故曰天下之能事毕也。孔子盖因序卦之次以明例，所谓举其一隅焉尔。神而明之，则知易道之周流而趋时无定，且知筮法之变通而触类可长。此义盖易之旁通至极处也。</p><p>有天地然后万物生焉</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li>项氏安世曰 ：屯不训盈也，当屯之时，刚柔始交，天地𬘡缊，雷雨动荡，见其气之充塞是也，是以谓之盈。尔故谓之盈者，其气也；谓之物之始生者，其时也；谓之难者，其事也。若屯之训，纷纭盘错之义云尔。</li></ul><p>屯者物之始生也</p><p>物生必蒙，故受之以蒙；蒙者蒙也，物之稚也，物稚不可不养也，故受之以需；需者饮食之道也，饮食必有讼，故受之以讼。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰 ：上言屯者盈也，释屯次乾坤，其言已毕，更言屯者物之始生者，开说下物生必蒙，直取始生之意，非重释屯之名也。</p></li><li><p>朱氏震曰 ：蒙冥昧也，物生者必始于冥昧，勾萌胎卵是也，故次之以蒙。童蒙也，物如此稚也。 又曰：饮食必有讼，干糇以愆，豕酒生祸，有血气者必有争心，故次之以讼。</p></li></ul><p>讼必有众起,故受之以师</p><p>师者众也，众必有所比，故受之以比；比者比也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>韩氏伯曰 ：众起而不比则争无由息，必相亲比而后得宁。</p></li><li><p>项氏安世曰 ：师比二卦相反，师取伍两卒旅师军之名，比取比闾族党州乡之名。师以众正为义，比以相亲为主。</p></li></ul><p>比必有所畜,故受之以小畜</p><p>物畜然后有礼，故受之以履；履而泰然后安，故受之以泰。</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>晁氏云：郑无而泰二字。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>姚氏信曰 ：安上治民，莫善于礼，有礼然后泰，泰然后安也。</p></li><li><p>项氏安世曰 ：履不训礼，人所履未有外于礼者，外于礼则非所当履，故以履为有礼也。上天下泽，亦有礼之名分焉。</p></li><li><p>胡氏一桂曰 ：乾坤至履，十变阴阳之气一周矣。</p></li></ul><p>泰者通也,物不可以终通，故受之以否；物不可以终否，故受之以同人；与人同者，物必归焉，故受之以大有；有大者不可以盈，故受之以谦；有大而能谦，必豫，故受之以豫。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>郭氏雍曰 ：以谦有大，则绝盈满之累，故优游不迫而暇豫也。</li></ul><p>豫必有随,故受之以随</p><p>以喜随人者，必有事故，受之以蛊；蛊者事也；有事而后可大，故受之以临；临者大也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>韩氏伯曰 ：可大之业，由事而生。</p></li><li><p>朱氏震曰 ：以喜随人，必有所事；臣事君子，事父妇事夫，弟子事师；非乐于所事者，其肯随乎。</p></li><li><p>项氏安世曰 ：蛊不训事，壊则万事生矣；事因坏而起，故以蛊为事之先。 又曰：临不训大，大者以上临下，以大临小；凡称临者，皆大者之事，故以大释之。若丰者大也，则真训大矣。</p></li><li><p>又曰：临不训大，大者以上临下，以大临小；凡称临者，皆大者之事，故以大释之。若丰者大也，则真训大矣。</p></li><li><p>吴氏澄曰 ：因蛊之有事，而后有临之盛大也。</p></li></ul><p>物大然后可观,故受之以观；可观而后有所合，故受之以噬嗑；嗑者合也；物不可以苟合而已，故受之以贲；贲者饰也；致饰然后亨，则尽矣，故受之以剥；剥者剥也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>崔氏憬曰 ：言德业大者，可以观于人也。</p></li><li><p>苏氏轼曰 ：君臣父子夫妇朋友之际，所谓合也，直情而行，谓之苟；礼以饰情，谓之贲；苟则易合，易则相渎；相渎则易以离；贲则难合，难合则相敬；相敬则能久；饰极则文胜而实衰，故剥。</p></li><li><p>张氏栻曰 ：贲饰则贵于文，文之太过，则又灭其质而有所不通，故致饰则亨，有所尽。</p></li></ul><p>物不可以终尽，剥穷上反下，故受之以复；复则不妄矣，故受之以无妄；有无妄然后可畜，故受之以大畜。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>崔氏憬曰 ：物复其本，则为诚实，故言复则无妄矣。</p></li><li><p>周子曰 ：不善之动，妄也；妄复则无妄矣；无妄则诚矣，故无妄次复。</p></li><li><p>郭氏忠孝曰 ：健为天德，大畜止健，畜天德也，故曰刚健笃实辉光日新，其德不能畜天德，则见于有为者，不能无妄，故天德止于大畜而动于无妄也。</p></li><li><p>阎氏彦升曰 ：无妄然后可畜，所畜者在德，故曰大。</p></li><li><p>余氏芑舒曰 ：自有事而大，大而可观，可观而合，合而饰，所谓忠信之薄而伪之始也，故一变而为剥；剥而复，则真实独存而不妄矣。</p></li><li><p>何氏楷曰 ：不妄与无妄，当辨由不妄然后能无妄也。</p></li></ul><p>物畜然后可养，故受之以颐；颐者养也；不养则不可动，故受之以大过；物不可以终过，故受之以坎；坎者陷也；陷必有所丽，故受之以离；离者丽也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏轼曰 ：养而不用其极，必动；动而不已，其极必过。</p></li><li><p>阎氏彦升曰 ：养者，君子所以成已；动者，君子所以应物；然君子处则中立，动则中行，岂求胜物哉？及其应变，则有时或过，故受之以大过。</p></li><li><p>林氏希元曰 ：不专一则不能直遂，不翕聚则不能发散，故必有养然后能动；不养则不可以动。孟子曰：人有不为也，而后可以有为，即此理也。故受之以大过；大过即动也，以大过之才，当大过之时而行大过之事，是之谓动而本于养也。</p></li><li><p>姜氏宝曰 ：无所养则其体不立，不可举动以应大事；惟养充而动，动必有大过，人者矣。</p></li></ul><p>有天地然后有万物，有万物然后有男女；有男女然后有夫妇；有夫妇然后有父子；有父子然后有君臣；有君臣然后有上下；有上下然后礼义有所错；夫妇之道不可以不久也，故受之以恒；恒者久也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>干氏宝曰 ：此详言人道三纲六纪，有自来也。人有男女阴阳之性，则自然有夫妇配合之道；阴阳化生血体相传，则自然有父子之亲；以父立君，以子资臣，则必有君臣之位；有君臣之位，故有上下之序；有上下之位，则必礼以定其体，义以制其宜。明先王制作，盖取之于情者也。上经始于乾坤，有生之本也；下经始于咸恒，人道之首也。易之兴也，当殷之末世，有妲己之祸；当周之盛德，有三母之功。以言天不地，不生；夫不妇，不成；相须之至，王教之端，故诗以闗睢为国风之始，而易于咸恒备论礼义所由生也。</p></li><li><p>朱子语类 ：问礼义有所错，错字陆氏两音如何曰？只是作措字，谓礼义有所设施耳。</p></li><li><p>吴氏澄曰 ：此言咸所以为下经之首也。夫妇谓咸卦，先言天地万物男女者，有夫妇之所由也；后言父子君臣上下者，有夫妇之所致也。有夫妇则其所生为父子，由家而国，虽非父子也，而君尊臣卑之分如父子也；由国而天下，虽非君臣而上贵下贱之分如君臣也。礼义所以分别尊卑贵贱之等，错犹置也。乾坤咸不出卦名者，以其为上下经之首卦，特别言之。</p></li></ul><p>物不可以久居其所，故受之以遁；遁者退也；物不可以终遁，故受之以大壮；物不可以终壮，故受之以晋；晋者进也；进必有所伤，故受之以明夷；夷者伤也；伤于外者必反其家，故受之以家人。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郭氏忠孝曰 ：伤乎外者必反其家，盖行有不得于人，则反求诸己。</p></li><li><p>阎氏彦升曰 ：知进而已，不知消息盈虚与时偕行，则伤之者至矣，故受之以明夷。以利合者，迫穷祸患害相弃也；以天属者，迫穷祸患害相收也。明夷之伤，岂得不反于家人乎？</p></li><li><p>何氏楷曰 ：晋与渐皆进，进必有归者，先以艮进，必有伤者，先以壮也。</p></li></ul><p>家道穷必乖，故受之以睽，睽者乖也；乖必有难，故受之以蹇；蹇者难也；物不可以终难，故受之以解；解者缓也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>周子曰 ：家人离必起于妇人，故睽次家人，以二女同居而志不同行也。</p></li><li><p>朱子语类 ：问缓字恐不是迟缓之缓，乃是懈怠之意，故曰解缓也。曰：缓是散漫意，问如纵弛之类，曰：然。</p></li><li><p>项氏安世曰 ：凡言屯者皆以为难，而蹇又称难者，卦皆有坎也。然屯动乎险中，行乎患难者也；蹇见险而止，但为所阻难，而不得前耳，非患难之难也。故居屯者必以经纶济之，遇蹇者待其解缓而后前。</p></li></ul><p>缓必有所失，故受之以损，损而不已必益，故受之以益；益而不已必决，故受之以夬；夬者决也；决必有所遇，故受之以姤；姤者遇也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱氏震曰 ：益久必盈，盈则必决，堤防是已，故次之以夬。</p></li><li><p>胡氏一桂曰 ：咸恒十变为损益，亦犹乾坤十变为否泰也。</p></li><li><p>俞氏琰曰 ：损益盛衰若循环然，损而不已天道复还，故必益；益而不已则所积满盈，故必决。此乃理之常也。损之后继以益，深谷为陵之意也；益之后继以夬，髙岸为谷之意也。</p></li></ul><p>物相遇而后聚，故受之以萃，萃者聚也；聚而上者谓之升，故受之以升；升而不已必困，故受之以困；困乎上者必反下，故受之以井。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>崔氏憬曰 ：冥升在上则穷，故言升而不已必困也。</p></li><li><p>张氏栻曰 ：天下之物散之则小，合而聚之则积；小以成其髙大，故聚而上者为升也。</p></li><li><p>项氏安世曰 ：物相遇而聚者，彼此之情交相会也，以众言之也；比而有所畜者，系而止之也，自我言之也。畜有止而聚之义，聚者不必止也。</p></li></ul><p>井道不可不革，故受之以革。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li>朱氏震曰 ：井在下者也，井久则秽浊不食，治井之道革去其害，井者而已。</li></ul><p>革物者莫若鼎，故受之以鼎；主器者莫若长子，故受之以震；震者动也，物不可以终动，止之故受之以艮；艮者止也，物不可以终止，故受之以渐；渐者进也，进必有所归，故受之以归妹；得其所归者必大，故受之以丰；丰者大也。</p><h3 id="集说-16" tabindex="-1">集说 <a class="header-anchor" href="#集说-16" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>阎氏彦升曰 ：晋者进也，进必有所伤；渐者进也，进必有归。何也？曰：晋所谓进者，有进而已，此进必有伤也；渐之所谓进者，渐进而已，乌有不得所归者乎？</p></li><li><p>朱氏震曰 ：前曰与人同者，物必归焉，故受之以大有；此曰得其所归者必大，大有次同人者，处大之道也；丰次归妹者，致大之道也。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>得其所归犹言得其所依归也，妇得贤夫而配之，臣得圣君而事之，皆得其所归之谓故同人之物必归焉者，人归已也；此之得其所归者，已归人也；两者皆足以致事业之大。</p><p>穷大者必失其居，故受之以旅；旅而无所容，故受之以巽；巽者入也。</p><h3 id="集说-17" tabindex="-1">集说 <a class="header-anchor" href="#集说-17" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郭氏雍曰 ：动极而止，止极复进，进极必伤，进以渐则有归，归得其所则大，穷其大则必失，盖非有大以谦故也。</p></li><li><p>张氏栻曰 ：旅者亲寡之时，无所容也，惟巽然后得所入，故受之以巽，而巽者入也。</p></li><li><p>俞氏琰曰 ：大而能谦，则豫；大而至于穷极，则必失其所安，故丰后继以旅。</p></li></ul><p>入而后说之，故受之以兑；兑者说也；说而后散之，故受之以涣；涣者离也。</p><h3 id="集说-18" tabindex="-1">集说 <a class="header-anchor" href="#集说-18" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张氏栻曰 ：入于道故有见而说，故受之以兑；惟说于道，故推而及人说，而后散，故受之以涣。</p></li><li><p>项氏安世曰 ：人之情相拒则怒，相入则说，故入而后说之。</p></li></ul><p>物不可以终离，故受之以节；节而信之，故受之以中孚；有其信者必行之，故受之以小过。</p><h3 id="集说-19" tabindex="-1">集说 <a class="header-anchor" href="#集说-19" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>韩氏伯曰 ：孚信也，既已有节，则宜信以守之；守其信者，则失贞而不谅之道，而以信为过，故曰小过也。</p></li><li><p>项氏安世曰 ：有其信犹书所谓有其善言，以此自负而居有之也；自恃其信者，其行必果，而过于中。</p></li><li><p>吴氏澄曰 ：过者行动而逾越之也，故大过云动，小过云行；凡行动未至其所为未及，既至其所为至，既至而又动又行，则为逾越其所至之地也，而过也。</p></li><li><p>蔡氏清曰 ：节而信之必立为节制，于此上之人当信而守之；下之人当信而行之，故受之以中孚；有其信者必行之；若果于自信，则于事不加详审，而在所必行矣，能免于过乎？</p></li></ul><p>有过物者必济，故受之以既济；物不可穷也，故受之以未济；终焉。</p><h3 id="集说-20" tabindex="-1">集说 <a class="header-anchor" href="#集说-20" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>韩氏伯曰 ：行过乎恭，用过乎俭，可以矫世励俗，有所济也。</p></li><li><p>项氏安世曰 ：大过则逾越常理，故必至于陷；小过或可济事，故有济而无陷也。坎离之交谓之既济，此生生不穷之所从出也，而圣人犹以为有穷也。又分之以为未济，此即咸感之后继之以恒久之义也。盖情之交者不可以久而无弊，故必以分之正者终之。</p></li></ul><p>总论</p><ul><li><p>王氏通中说 ：赞易至序卦曰，大哉时之相生也，逹者可与几矣。至杂卦曰，旁行而不流，守者可与存义矣。</p></li><li><p>邵子曰 ：乾坤天地之本，坎离天地之用，是以易始于乾坤，中于坎离，终于既未济。而泰否为上经之中，咸恒为下经之首，皆言乎其用也。 又曰：乾坤坎离为上篇之用，兑艮震巽为下篇之用也，颐中孚大过小过为二篇之正也。 又曰：自乾坤至坎离，以天道也；自咸恒至既济未济，以人事也。</p></li><li><p>又曰：乾坤坎离为上篇之用，兑艮震巽为下篇之用也，颐中孚大过小过为二篇之正也。</p></li><li><p>又曰：自乾坤至坎离，以天道也；自咸恒至既济未济，以人事也。</p></li><li><p>程子 ：上下篇义曰，乾坤天地之道，阴阳之本，故为上篇之首。坎离阴阳之成质，故为上篇之终。咸恒夫妇之道，生育之本，故为下篇之首。未济坎离之合，既济坎离之交，合而交则生物，阴阳之成功也，故为下篇之终。二篇之卦既分，而后推其义以为之次序，卦是也。卦之分则以阴阳，阳盛者居上，阴盛者居下。所谓盛者，或以卦或以爻，卦与爻取义有不同。如剥以卦言，则阴长阳剥也；以爻言，则阳极于上，又一阳为众阴主也。如大壮以卦言，则阳长而壮；以爻言，则阴盛于上，用各于其所，不相害也。干父也，莫亢焉，坤母也，非干无与为敌也。故卦有干者居上篇，有坤者居下篇。而复阳生临阳长观阳盛剥阳极，则虽有坤而居上。姤阴生遁阴长大壮阴盛夬阴极，则虽有干而居下。其馀有干者皆在上篇，泰否需讼小畜履同人大有无妄大畜也有坤而在上篇，皆一阳之卦也。卦五阴而一阳，则一阳为之主，故一阳之卦皆在上篇，师谦豫比复剥也。其馀有坤者皆在下篇，晋明夷萃升也。卦一阴五阳者皆有干也，又阳众而盛也，虽众阳说于一阴，说之而已，非如一阳为众阴主也。王弼云：一阴为之主，非也。故一阴之卦皆在上篇，小畜履同人大有也。卦二阳者有坤则居下篇，小过虽无坤，阴过之卦也，亦在下篇。其馀二阳之卦皆一阳生于下而逹于上，又二体皆阳，阳之盛也，皆在上篇，屯蒙颐习坎也。阳生于下，谓震坎在下，震生于下也，坎始于中也逹于上，谓一阳至上或得正位，生于下而上逹，阳畅之盛也。阳生于下而不逹于上，又阴众而阳寡，复失正位，阳之弱也，震也解也，上有阳而下无阳，无本也，艮也蹇也。震坎艮以卦言则阳也，以爻言则皆始变㣲也，而震之上艮之下无阳，坎则阳陷皆非盛也，惟习坎则阳上逹矣，故为盛卦。二阴者有干则阳盛可知，需讼大畜无妄也。无干而为盛者，大过也离也，大过阳盛于中，上下之阴弱矣，阳居上下则纲纪于阴，颐是也。阴居上下不能主制于阳而反弱也，必上下各二阴中惟两阳然后为胜，小过是也。大过小过之名可见也，离则二体上下皆阳，阴实丽焉，阳之盛也。其馀二阴之卦二体俱阴，阴盛也，皆在下篇，家人睽革鼎㢲兑中孚也。卦三阴三阳者敌也，则以义为胜，阴阳尊卑之义，男女长少之序，天地之大经也。阳少于阴而居上，则为胜，蛊少阳居长阴上，贲少男在中女上，皆阳盛也。坎虽阳卦而阳为阴所陷溺也，又与阴卦重阴盛也，故阴阳敌而有坎者皆在下篇，困井涣节既济未济也。或曰一体有坎尚为阳陷，二体皆坎反为阳盛何也？曰：一体有坎，阳为阴所陷，又重于阴也。二体皆坎，阳生于下而逹于上，又二体皆阳，可谓盛矣。男在女上乃理之常，未为盛也。若失正位而阴反居尊，则弱也，故恒损归妹丰皆在下篇，女在男上阴之胜也。凡女居上者皆在下篇，咸益渐旅困涣未济也。唯随与噬嗑则男下女非女胜男也，故随之彖曰刚来而下柔，噬嗑彖曰柔得中而上行，长阳非少阴可敌以长男下中少女故为下之若长少敌势力侔，则阴在上为陵阳在下为弱，咸益之类是也。咸亦有下女之象，非以长下少也，乃二少相感以相与所以致陵也，故有利贞之戒。困虽女少于男，乃阳陷而为阴揜无相下之义也。小过二阳居四阴之中，则为阴盛中孚二阴居四阳之中而不为阳盛何也？曰：阳体实中乎中虚也。然则颐中四阴不为虚乎？曰：颐二体皆阳卦而本末皆阳盛之至也，中孚二体皆阴卦上下各二阳不成本末之象，以其中虚故为中孚，阴盛可知矣。</p></li><li><p>项氏安世曰 ：上经言天地生万物以气而流形，故始于乾坤，终于坎离，言气化之本也。下经言万物之相生以形而传气，故始于咸恒，终于既济未济，言夫妇之道也。</p></li><li><p>蔡氏清曰 ：序卦之义有相反者有相因者，相反者极而变者也，相因者其未至于极者也，总不出此二例。</p></li></ul>',75)])])}const u=a(r,[["render",h]]);export{b as __pageData,u as default};
